/**
 * Builds in-memory ZIP archives and .NET tool packages for tests. Entries are stored
 * uncompressed so tests can create deliberately malformed names and attributes that
 * regular ZIP writers refuse to produce.
 */

export interface ZipFixtureEntry {
    name: string;
    data?: string | Buffer;
    mode?: number;
}

const CRC_TABLE = Array.from({ length: 256 }, (_, index) => {
    let value = index;
    for (let bit = 0; bit < 8; bit++) value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
    return value >>> 0;
});

function crc32(buffer: Buffer): number {
    let crc = 0xffffffff;
    for (const byte of buffer) crc = CRC_TABLE[(crc ^ byte) & 0xff] ^ (crc >>> 8);
    return (crc ^ 0xffffffff) >>> 0;
}

export function buildZip(entries: ZipFixtureEntry[]): Buffer {
    const locals: Buffer[] = [];
    const centrals: Buffer[] = [];
    let offset = 0;
    for (const entry of entries) {
        const name = Buffer.from(entry.name, "utf8");
        const data = Buffer.isBuffer(entry.data) ? entry.data : Buffer.from(entry.data ?? "", "utf8");
        const crc = crc32(data);
        const local = Buffer.alloc(30);
        local.writeUInt32LE(0x04034b50, 0);
        local.writeUInt16LE(20, 4);
        local.writeUInt16LE(0x0800, 6);
        local.writeUInt16LE(0, 8);
        local.writeUInt16LE(0, 10);
        local.writeUInt16LE(0x21, 12);
        local.writeUInt32LE(crc, 14);
        local.writeUInt32LE(data.length, 18);
        local.writeUInt32LE(data.length, 22);
        local.writeUInt16LE(name.length, 26);
        local.writeUInt16LE(0, 28);
        const central = Buffer.alloc(46);
        central.writeUInt32LE(0x02014b50, 0);
        central.writeUInt16LE((3 << 8) | 20, 4);
        central.writeUInt16LE(20, 6);
        central.writeUInt16LE(0x0800, 8);
        central.writeUInt16LE(0, 10);
        central.writeUInt16LE(0, 12);
        central.writeUInt16LE(0x21, 14);
        central.writeUInt32LE(crc, 16);
        central.writeUInt32LE(data.length, 20);
        central.writeUInt32LE(data.length, 24);
        central.writeUInt16LE(name.length, 28);
        central.writeUInt32LE(((entry.mode ?? 0o100644) << 16) >>> 0, 38);
        central.writeUInt32LE(offset, 42);
        locals.push(local, name, data);
        centrals.push(central, name);
        offset += local.length + name.length + data.length;
    }
    const directory = Buffer.concat(centrals);
    const end = Buffer.alloc(22);
    end.writeUInt32LE(0x06054b50, 0);
    end.writeUInt16LE(entries.length, 8);
    end.writeUInt16LE(entries.length, 10);
    end.writeUInt32LE(directory.length, 12);
    end.writeUInt32LE(offset, 16);
    return Buffer.concat([...locals, directory, end]);
}

export interface ToolPackageFixture {
    packageId: string;
    version: string;
    command: string;
    targetFramework?: string;
    minimumRuntimeVersion?: string;
    rollForward?: string;
    packageType?: string | null;
    nuspecId?: string;
    toolSettings?: string;
    runtimeConfig?: string;
    deps?: string;
    omit?: string[];
    extra?: ZipFixtureEntry[];
}

export function toolPackageEntries(options: ToolPackageFixture): ZipFixtureEntry[] {
    const targetFramework = options.targetFramework ?? "net8.0";
    const runtimeVersion = targetFramework.slice(3);
    const root = `tools/${targetFramework}/any`;
    const packageType = options.packageType === undefined ? "DotnetTool" : options.packageType;
    const entries: ZipFixtureEntry[] = [
        { name: "[Content_Types].xml", data: "<Types />" },
        { name: "_rels/.rels", data: "<Relationships />" },
        { name: "package/services/metadata/core-properties/abc.psmdcp", data: "<coreProperties />" },
        {
            name: `${options.packageId}.nuspec`,
            data: `<?xml version="1.0" encoding="utf-8"?>\n<!-- generated by dotnet pack -->\n<package xmlns="http://schemas.microsoft.com/packaging/2013/05/nuspec.xsd"><metadata><id>${options.nuspecId ?? options.packageId}</id><version>${options.version}</version><description>Test &amp; fixture</description>${packageType ? `<packageTypes><packageType name="${packageType}" /></packageTypes>` : ""}</metadata></package>`,
        },
        {
            name: `${root}/DotnetToolSettings.xml`,
            data:
                options.toolSettings ??
                `<?xml version="1.0" encoding="utf-8"?>\n<DotNetCliTool Version="1"><Commands><Command Name="${options.command}" EntryPoint="Worker.dll" Runner="dotnet" /></Commands></DotNetCliTool>`,
        },
        { name: `${root}/Worker.dll`, data: "fixture assembly bytes" },
        { name: `${root}/Dependency.dll`, data: "fixture dependency bytes" },
        {
            name: `${root}/Worker.runtimeconfig.json`,
            data:
                options.runtimeConfig ??
                JSON.stringify({
                    runtimeOptions: {
                        tfm: targetFramework,
                        framework: { name: "Microsoft.NETCore.App", version: options.minimumRuntimeVersion ?? "8.0.0" },
                        ...(options.rollForward ? { rollForward: options.rollForward } : {}),
                    },
                }),
        },
        {
            name: `${root}/Worker.deps.json`,
            data:
                options.deps ??
                JSON.stringify({
                    runtimeTarget: { name: `.NETCoreApp,Version=v${runtimeVersion}` },
                    targets: {
                        [`.NETCoreApp,Version=v${runtimeVersion}`]: {
                            "Worker/1.2.0": { runtime: { "Worker.dll": {} }, dependencies: { Dependency: "1.0.0" } },
                            "Dependency/1.0.0": { runtime: { [`lib/${targetFramework}/Dependency.dll`]: {} } },
                        },
                    },
                    libraries: { "Worker/1.2.0": { type: "project" }, "Dependency/1.0.0": { type: "package" } },
                }),
        },
    ];
    return [...entries.filter((entry) => !options.omit?.includes(entry.name)), ...(options.extra ?? [])];
}

export function buildToolPackage(options: ToolPackageFixture): Buffer {
    return buildZip(toolPackageEntries(options));
}
